-- Todas dentro de Colombia continental e insular, o la migración está mal.
do $$
declare
  v_fuera int;
begin
  select count(*) into v_fuera
    from public.municipios
   where latitud is not null
     and (latitud not between -4.3 and 13.5 or longitud not between -82 and -66);
  if v_fuera > 0 then
    raise exception 'Coordenada fuera de Colombia en % municipios', v_fuera;
  end if;
end $$;
